Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
iommu/mediatek: fix use-after-free on probe deferral

The driver is dropping the references taken to the larb devices during
probe after successful lookup as well as on errors. This can
potentially lead to a use-after-free in case a larb device has not yet
been bound to its driver so that the iommu driver probe defers.

Fix this by keeping the references as expected while the iommu driver is
bound.

Fixes: 26593928564c ("iommu/mediatek: Add error path for loop of mm_dts_parse")
Cc: stable@vger.kernel.org
Cc: Yong Wu <yong.wu@mediatek.com>
Acked-by: Robin Murphy <robin.murphy@arm.com>
Signed-off-by: Johan Hovold <johan@kernel.org>
Reviewed-by: Yong Wu <yong.wu@mediatek.com>
Reviewed-by: AngeloGioacchino Del Regno <angelogioacchino.delregno@collabora.com>
Signed-off-by: Joerg Roedel <joerg.roedel@amd.com>

Here is the root cause:
In mtk_iommu_mm_dts_parse, the driver prematurely dropped the reference to each larb device via platform_device_put after matching it, even though the device reference needed to remain valid for the driver's lifetime. This could cause a use-after-free if the larb device had not yet bound to its driver and the iommu probe was deferred, allowing the larb device to be freed while still required.

Here is the patch:

 static int mtk_iommu_mm_dts_parse(struct device *dev, struct component_match **match,
 				  struct mtk_iommu_data *data)
 {
 	struct device_node *larbnode, *frst_avail_smicomm_node = NULL;
 	struct platform_device *plarbdev, *pcommdev;
 	struct device_link *link;
 	int i, larb_nr, ret;

 	larb_nr = of_count_phandle_with_args(dev->of_node, "mediatek,larbs", NULL);
 	if (larb_nr < 0)
 		return larb_nr;
 	if (larb_nr == 0 || larb_nr > MTK_LARB_NR_MAX)
 		return -EINVAL;

 	for (i = 0; i < larb_nr; i++) {
 		struct device_node *smicomm_node, *smi_subcomm_node;
 		u32 id;

 		larbnode = of_parse_phandle(dev->of_node, "mediatek,larbs", i);
 		if (!larbnode) {
 			ret = -EINVAL;
 			goto err_larbdev_put;
 		}

 		if (!of_device_is_available(larbnode)) {
 			of_node_put(larbnode);
 			continue;
 		}

 		ret = of_property_read_u32(larbnode, "mediatek,larb-id", &id);
 		if (ret)/* The id is consecutive if there is no this property */
 			id = i;
 		if (id >= MTK_LARB_NR_MAX) {
 			of_node_put(larbnode);
 			ret = -EINVAL;
 			goto err_larbdev_put;
 		}

 		plarbdev = of_find_device_by_node(larbnode);
 		of_node_put(larbnode);
 		if (!plarbdev) {
 			ret = -ENODEV;
 			goto err_larbdev_put;
 		}
 		if (data->larb_imu[id].dev) {
 			platform_device_put(plarbdev);
 			ret = -EEXIST;
 			goto err_larbdev_put;
 		}
 		data->larb_imu[id].dev = &plarbdev->dev;

 		if (!plarbdev->dev.driver) {
 			ret = -EPROBE_DEFER;
 			goto err_larbdev_put;
 		}

 		/* Get smi-(sub)-common dev from the last larb. */
 		smi_subcomm_node = of_parse_phandle(larbnode, "mediatek,smi", 0);
 		if (!smi_subcomm_node) {
 			ret = -EINVAL;
 			goto err_larbdev_put;
 		}

 		/*
 		 * It may have two level smi-common. the node is smi-sub-common if it
 		 * has a new mediatek,smi property. otherwise it is smi-commmon.
 		 */
 		smicomm_node = of_parse_phandle(smi_subcomm_node, "mediatek,smi", 0);
 		if (smicomm_node)
 			of_node_put(smi_subcomm_node);
 		else
 			smicomm_node = smi_subcomm_node;

 		/*
 		 * All the larbs that connect to one IOMMU must connect with the same
 		 * smi-common.
 		 */
 		if (!frst_avail_smicomm_node) {
 			frst_avail_smicomm_node = smicomm_node;
 		} else if (frst_avail_smicomm_node != smicomm_node) {
 			dev_err(dev, "mediatek,smi property is not right @larb%d.", id);
 			of_node_put(smicomm_node);
 			ret = -EINVAL;
 			goto err_larbdev_put;
 		} else {
 			of_node_put(smicomm_node);
 		}

 		component_match_add(dev, match, component_compare_dev, &plarbdev->dev);
-		platform_device_put(plarbdev);
 	}

-	if (!frst_avail_smicomm_node)
-		return -EINVAL;
+	if (!frst_avail_smicomm_node) {
+		ret = -EINVAL;
+		goto err_larbdev_put;
+	}

 	pcommdev = of_find_device_by_node(frst_avail_smicomm_node);
 	of_node_put(frst_avail_smicomm_node);
-	if (!pcommdev)
-		return -ENODEV;
+	if (!pcommdev) {
+		ret = -ENODEV;
+		goto err_larbdev_put;
+	}
 	data->smicomm_dev = &pcommdev->dev;

 	link = device_link_add(data->smicomm_dev, dev,
 			       DL_FLAG_STATELESS | DL_FLAG_PM_RUNTIME);
 	platform_device_put(pcommdev);
 	if (!link) {
 		dev_err(dev, "Unable to link %s.\n", dev_name(data->smicomm_dev));
-		return -EINVAL;
+		ret = -EINVAL;
+		goto err_larbdev_put;
 	}
 	return 0;

 err_larbdev_put:
 	for (i = MTK_LARB_NR_MAX - 1; i >= 0; i--) {
 		if (!data->larb_imu[i].dev)
 			continue;
 		put_device(data->larb_imu[i].dev);
 	}
 	return ret;
 }

 static int mtk_iommu_probe(struct platform_device *pdev)
 {
 	struct mtk_iommu_data   *data;
 	struct device           *dev = &pdev->dev;
 	struct resource         *res;
 	resource_size_t		ioaddr;
 	struct component_match  *match = NULL;
 	struct regmap		*infracfg;
 	void                    *protect;
 	int                     ret, banks_num, i = 0;
 	u32			val;
 	char                    *p;
 	struct mtk_iommu_bank_data *bank;
 	void __iomem		*base;

 	data = devm_kzalloc(dev, sizeof(*data), GFP_KERNEL);
 	if (!data)
 		return -ENOMEM;
 	data->dev = dev;
 	data->plat_data = of_device_get_match_data(dev);

 	/* Protect memory. HW will access here while translation fault.*/
 	protect = devm_kcalloc(dev, 2, MTK_PROTECT_PA_ALIGN, GFP_KERNEL);
 	if (!protect)
 		return -ENOMEM;
 	data->protect_base = ALIGN(virt_to_phys(protect), MTK_PROTECT_PA_ALIGN);

 	if (MTK_IOMMU_HAS_FLAG(data->plat_data, HAS_4GB_MODE)) {
 		infracfg = syscon_regmap_lookup_by_phandle(dev->of_node, "mediatek,infracfg");
 		if (IS_ERR(infracfg)) {
 			/*
 			 * Legacy devicetrees will not specify a phandle to
 			 * mediatek,infracfg: in that case, we use the older
 			 * way to retrieve a syscon to infra.
 			 *
 			 * This is for retrocompatibility purposes only, hence
 			 * no more compatibles shall be added to this.
 			 */
 			switch (data->plat_data->m4u_plat) {
 			case M4U_MT2712:
 				p = "mediatek,mt2712-infracfg";
 				break;
 			case M4U_MT8173:
 				p = "mediatek,mt8173-infracfg";
 				break;
 			default:
 				p = NULL;
 			}

 			infracfg = syscon_regmap_lookup_by_compatible(p);
 			if (IS_ERR(infracfg))
 				return PTR_ERR(infracfg);
 		}

 		ret = regmap_read(infracfg, REG_INFRA_MISC, &val);
 		if (ret)
 			return ret;
 		data->enable_4GB = !!(val & F_DDR_4GB_SUPPORT_EN);
 	}

 	banks_num = data->plat_data->banks_num;
 	res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
 	if (!res)
 		return -EINVAL;
 	if (resource_size(res) < banks_num * MTK_IOMMU_BANK_SZ) {
 		dev_err(dev, "banknr %d. res %pR is not enough.\n", banks_num, res);
 		return -EINVAL;
 	}
 	base = devm_ioremap_resource(dev, res);
 	if (IS_ERR(base))
 		return PTR_ERR(base);
 	ioaddr = res->start;

 	data->bank = devm_kmalloc(dev, banks_num * sizeof(*data->bank), GFP_KERNEL);
 	if (!data->bank)
 		return -ENOMEM;

 	do {
 		if (!data->plat_data->banks_enable[i])
 			continue;
 		bank = &data->bank[i];
 		bank->id = i;
 		bank->base = base + i * MTK_IOMMU_BANK_SZ;
 		bank->m4u_dom = NULL;

 		bank->irq = platform_get_irq(pdev, i);
 		if (bank->irq < 0)
 			return bank->irq;
 		bank->parent_dev = dev;
 		bank->parent_data = data;
 		spin_lock_init(&bank->tlb_lock);
 	} while (++i < banks_num);

 	if (MTK_IOMMU_HAS_FLAG(data->plat_data, HAS_BCLK)) {
 		data->bclk = devm_clk_get(dev, "bclk");
 		if (IS_ERR(data->bclk))
 			return PTR_ERR(data->bclk);
 	}

 	if (MTK_IOMMU_HAS_FLAG(data->plat_data, PGTABLE_PA_35_EN)) {
 		ret = dma_set_mask(dev, DMA_BIT_MASK(35));
 		if (ret) {
 			dev_err(dev, "Failed to set dma_mask 35.\n");
 			return ret;
 		}
 	}

 	pm_runtime_enable(dev);

 	if (MTK_IOMMU_IS_TYPE(data->plat_data, MTK_IOMMU_TYPE_MM)) {
 		ret = mtk_iommu_mm_dts_parse(dev, &match, data);
 		if (ret) {
 			dev_err_probe(dev, ret, "mm dts parse fail\n");
 			goto out_runtime_disable;
 		}
 	} else if (MTK_IOMMU_IS_TYPE(data->plat_data, MTK_IOMMU_TYPE_INFRA) &&
 		   !MTK_IOMMU_HAS_FLAG(data->plat_data, CFG_IFA_MASTER_IN_ATF)) {
 		p = data->plat_data->pericfg_comp_str;
 		data->pericfg = syscon_regmap_lookup_by_compatible(p);
 		if (IS_ERR(data->pericfg)) {
 			ret = PTR_ERR(data->pericfg);
 			goto out_runtime_disable;
 		}
 	}

 	platform_set_drvdata(pdev, data);
 	mutex_init(&data->mutex);

 	if (MTK_IOMMU_HAS_FLAG(data->plat_data, SHARE_PGTABLE)) {
 		list_add_tail(&data->list, data->plat_data->hw_list);
 		data->hw_list = data->plat_data->hw_list;
 	} else {
 		INIT_LIST_HEAD(&data->hw_list_head);
 		list_add_tail(&data->list, &data->hw_list_head);
 		data->hw_list = &data->hw_list_head;
 	}

 	ret = iommu_device_sysfs_add(&data->iommu, dev, NULL,
 				     "mtk-iommu.%pa", &ioaddr);
 	if (ret)
 		goto out_list_del;

 	ret = iommu_device_register(&data->iommu, &mtk_iommu_ops, dev);
 	if (ret)
 		goto out_sysfs_remove;

 	if (MTK_IOMMU_IS_TYPE(data->plat_data, MTK_IOMMU_TYPE_MM)) {
 		ret = component_master_add_with_match(dev, &mtk_iommu_com_ops, match);
 		if (ret)
 			goto out_device_unregister;
 	}
 	return ret;

 out_device_unregister:
 	iommu_device_unregister(&data->iommu);
 out_sysfs_remove:
 	iommu_device_sysfs_remove(&data->iommu);
 out_list_del:
 	list_del(&data->list);
-	if (MTK_IOMMU_IS_TYPE(data->plat_data, MTK_IOMMU_TYPE_MM))
+	if (MTK_IOMMU_IS_TYPE(data->plat_data, MTK_IOMMU_TYPE_MM)) {
 		device_link_remove(data->smicomm_dev, dev);
+
+		for (i = 0; i < MTK_LARB_NR_MAX; i++)
+			put_device(data->larb_imu[i].dev);
+	}
 out_runtime_disable:
 	pm_runtime_disable(dev);
 	return ret;
 }

 static void mtk_iommu_remove(struct platform_device *pdev)
 {
 	struct mtk_iommu_data *data = platform_get_drvdata(pdev);
 	struct mtk_iommu_bank_data *bank;
 	int i;

 	iommu_device_sysfs_remove(&data->iommu);
 	iommu_device_unregister(&data->iommu);

 	list_del(&data->list);

 	if (MTK_IOMMU_IS_TYPE(data->plat_data, MTK_IOMMU_TYPE_MM)) {
 		device_link_remove(data->smicomm_dev, &pdev->dev);
 		component_master_del(&pdev->dev, &mtk_iommu_com_ops);
+
+		for (i = 0; i < MTK_LARB_NR_MAX; i++)
+			put_device(data->larb_imu[i].dev);
 	}
 	pm_runtime_disable(&pdev->dev);
 	for (i = 0; i < data->plat_data->banks_num; i++) {
 		bank = &data->bank[i];
 		if (!bank->m4u_dom)
 			continue;
 		devm_free_irq(&pdev->dev, bank->irq, bank);
 	}
 }



